function fail(message) {
  console.error(`\nERROR: ${message}`);
  process.exit(1);
}

function git(args) {
  try {
    return execFileSync("git", args, {
      cwd: root,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    }).trim();
  } catch {
    fail("Jalankan script ini dari root repository asihjaya-rms.");
  }
}

git(["rev-parse", "--show-toplevel"]);

function parsePatch(text) {
  const lines = text.split("\n");
  const files = [];
  let file = null;
  let hunk = null;

  const finishHunk = () => {
    if (file && hunk) file.hunks.push(hunk);
    hunk = null;
  };

  const finishFile = () => {
    finishHunk();
    if (file) files.push(file);
    file = null;
  };

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];

    if (line.startsWith("diff --git ")) {
      finishFile();
      const match = /^diff --git a\/(.+) b\/(.+)$/.exec(line);
      if (!match || match[1] !== match[2]) {
        fail(`Diff path tidak didukung pada baris ${i + 1}.`);
      }
      file = { path: match[1], isNew: false, hunks: [] };
      continue;
    }

    if (!file) continue;

    if (line === "new file mode 100644") {
      file.isNew = true;
      continue;
    }

    if (line.startsWith("@@ ")) {
      finishHunk();
      const match = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(line);
      if (!match) fail(`Header hunk tidak valid: ${line}`);
      hunk = {
        header: line,
        oldStart: Number(match[1]),
        oldCount: Number(match[2] ?? "1"),
        newStart: Number(match[3]),
        newCount: Number(match[4] ?? "1"),
        lines: [],
      };
      continue;
    }

    if (hunk) {
      if (
        line.startsWith(" ") ||
        line.startsWith("+") ||
        line.startsWith("-") ||
        line === "\\ No newline at end of file"
      ) {
        hunk.lines.push(line);
      }
    }
  }

  finishFile();
  return files;
}

function hunkParts(hunk) {
  const oldLines = [];
  const newLines = [];

  for (const line of hunk.lines) {
    if (line === "\\ No newline at end of file") continue;
    const marker = line[0];
    const body = line.slice(1);
    if (marker === " " || marker === "-") oldLines.push(body);
    if (marker === " " || marker === "+") newLines.push(body);
  }
  return { oldLines, newLines };
}

function matchesAt(lines, start, expected) {
  if (start < 0 || start + expected.length > lines.length) return false;
  for (let i = 0; i < expected.length; i += 1) {
    if (lines[start + i] !== expected[i]) return false;
  }
  return true;
}

function findNearestMatch(lines, expectedLines, target, radius = 160) {
  if (expectedLines.length === 0) return target;

  const min = Math.max(0, target - radius);
  const max = Math.min(lines.length - expectedLines.length, target + radius);
  let best = null;
  let bestDistance = Infinity;

  for (let start = min; start <= max; start += 1) {
    if (!matchesAt(lines, start, expectedLines)) continue;
    const distance = Math.abs(start - target);
    if (distance < bestDistance) {
      best = start;
      bestDistance = distance;
    }
  }
  return best;
}

const files = parsePatch(patch);
if (!files.length) fail("Embedded revision tidak berisi perubahan.");

const stagedOutputs = new Map();
const changed = [];
const alreadyApplied = [];

for (const file of files) {
  const absolutePath = path.join(root, file.path);
  const exists = existsSync(absolutePath);

  let lineEnding = "\n";
  let hadFinalNewline = true;
  let lines = [];

  if (exists) {
    const raw = readFileSync(absolutePath, "utf8");
    lineEnding = raw.includes("\r\n") ? "\r\n" : "\n";
    hadFinalNewline = raw.endsWith("\n");
    const normalized = raw.replace(/\r\n/g, "\n");
    lines = normalized.split("\n");
    if (hadFinalNewline) lines.pop();
  } else if (!file.isNew) {
    fail(`File target tidak ditemukan: ${file.path}`);
  }

  let offset = 0;
  let fileChanged = false;

  for (const hunk of file.hunks) {
    const { oldLines, newLines } = hunkParts(hunk);

    if (file.isNew && oldLines.length === 0 && !exists && lines.length === 0) {
      lines = [...newLines];
      offset += newLines.length;
      fileChanged = true;
      continue;
    }

    const expectedOld = Math.max(0, hunk.oldStart - 1 + offset);

    // Jalur utama: posisi hunk asli.
    let position = matchesAt(lines, expectedOld, oldLines) ? expectedOld : null;

    // Fallback aman: cari kecocokan exact terdekat dari posisi asli.
    if (position === null) {
      position = findNearestMatch(lines, oldLines, expectedOld);
    }

    if (position !== null) {
      lines.splice(position, oldLines.length, ...newLines);
      offset += newLines.length - oldLines.length;
      fileChanged = true;
      continue;
    }

    // Idempotency: bila sisi baru sudah ada di sekitar posisi baru, anggap hunk sudah terpasang.
    const expectedNew = Math.max(0, hunk.newStart - 1);
    let newPosition = matchesAt(lines, expectedNew, newLines) ? expectedNew : null;
    if (newPosition === null) {
      newPosition = findNearestMatch(lines, newLines, expectedNew);
    }

    if (newPosition !== null) {
      offset += newLines.length - oldLines.length;
      continue;
    }

    fail(
      `Tidak dapat mencocokkan ${file.path} ${hunk.header}. ` +
      "Tidak ada file source yang ditulis."
    );
  }

  if (!fileChanged) {
    alreadyApplied.push(file.path);
    continue;
  }

  let output = lines.join("\n");
  if (hadFinalNewline || file.isNew) output += "\n";
  if (lineEnding === "\r\n") output = output.replace(/\n/g, "\r\n");

  stagedOutputs.set(file.path, output);
  changed.push(file.path);
}

// Semua hunk pada semua file sudah lolos validasi. Baru menulis sekarang.
for (const [relativePath, content] of stagedOutputs) {
  const absolutePath = path.join(root, relativePath);
  mkdirSync(path.dirname(absolutePath), { recursive: true });
  writeFileSync(absolutePath, content, "utf8");
}

console.log("\nOK: revisi Quick Create Kategori & Warna berhasil diterapkan.");
console.log(`File source berubah: ${changed.length}`);
for (const file of changed) console.log(`  ${file}`);

if (alreadyApplied.length) {
  console.log(`\nSudah terpasang sebelumnya: ${alreadyApplied.length}`);
  for (const file of alreadyApplied) console.log(`  ${file}`);
}

console.log("\nGit status:");
console.log(git(["status", "--short"]) || "(clean)");

console.log("\nValidasi selanjutnya:");
console.log("  npm run lint");
console.log("  npm run typecheck");
